  "html": "<a class=\"skip\" href=\"#main\">Skip to content</a><div id=\"template-bar\">Free HTML template. <a href=\"index.html\" download=\"product-launch.html\">Download this template (free)</a> &nbsp;|&nbsp; <a href=\"https://mmrahmanbappi.github.io/100-free-html-templates/\">See all free templates</a></div><header><nav class=\"wrap nav\" aria-label=\"Main\"><a href=\"#\" class=\"logo\">lumo</a><ul class=\"menu\" id=\"menu\"><li><a href=\"#try\">Try it</a></li><li><a href=\"#features\">Features</a></li><li><a href=\"#reserve\" class=\"cta\">Reserve yours</a></li></ul><button class=\"burger\" aria-label=\"Open menu\" aria-expanded=\"false\" aria-controls=\"menu\">☰</button></nav></header><main id=\"main\"><section class=\"hero\" id=\"try\" aria-labelledby=\"h1\"><div class=\"wrap hg\"><div><span class=\"pill\">Launching 1 December</span><h1 id=\"h1\">The desk lamp that follows the sun.</h1><p>Lumo shifts from cool daylight in the morning to warm amber at night, so your eyes feel less tired after a long day at the screen.</p><div class=\"cd\" aria-label=\"Countdown to launch\"><div><b id=\"cD\">0</b><span>days</span></div><div><b id=\"cH\">0</b><span>hours</span></div><div><b id=\"cM\">0</b><span>minutes</span></div></div><a class=\"btn\" href=\"#reserve\">Reserve for $89</a></div><div class=\"stage\"><div class=\"ctl\"><div><label for=\"ct\">Colour <output id=\"cto\" for=\"ct\">4000K</output></label><input id=\"ct\" type=\"range\" min=\"2200\" max=\"6500\" step=\"100\" value=\"4000\"></div><div><label for=\"br\">Brightness <output id=\"bro\" for=\"br\">70%</output></label><input id=\"br\" type=\"range\" min=\"10\" max=\"100\" value=\"70\"></div></div><div class=\"sw\" role=\"group\" aria-label=\"Lamp finish\"><span>Finish:</span><button type=\"button\" aria-pressed=\"true\" data-c=\"#DDE3DD\" aria-label=\"Sage\"></button><button type=\"button\" aria-pressed=\"false\" data-c=\"#E8DCC8\" aria-label=\"Sand\"></button><button type=\"button\" aria-pressed=\"false\" data-c=\"#6B6F72\" aria-label=\"Graphite\"></button><span id=\"fn\">Sage</span></div></div></div></section><section class=\"ft\" id=\"features\" aria-labelledby=\"f1\"><div class=\"wrap\"><div class=\"sh\"><h2 id=\"f1\">Small lamp, lots of thought</h2><p>Tap through the features.</p></div><div class=\"tabs\" id=\"tabs\" role=\"group\" aria-label=\"Features\"></div><div class=\"fp\" aria-live=\"polite\"><div><h3 id=\"fh\"></h3><p id=\"fd\"></p></div><div class=\"big\" id=\"fb\"></div></div></div></section><section class=\"eb\" id=\"reserve\" aria-labelledby=\"r1\"><div class=\"wrap\"><div class=\"box\"><div><h2 id=\"r1\">Early bird: $89</h2><p>Reserve now for a $10 deposit. Pay the rest when it ships in January. Change your mind any time and we refund the deposit.</p><div class=\"stk\" aria-hidden=\"true\"><i id=\"sb\"></i></div><small id=\"sn\" aria-live=\"polite\"></small></div><div><div class=\"price\">$89<s>$129</s></div><form class=\"rf\" id=\"rf\"><label for=\"re\">Email address</label><input id=\"re\" type=\"email\" placeholder=\"Your email\" required autocomplete=\"email\"><button class=\"btn\" type=\"submit\">Reserve for $10</button></form><p class=\"msg\" id=\"msg\" role=\"status\"></p></div></div></div></section></main><footer><div class=\"wrap\"><p>© <span id=\"yr\"></span> Lumo Lighting Co., Copenhagen</p><p><a href=\"https://unsplash.com\">Photos: Unsplash</a> &nbsp;|&nbsp; <a href=\"https://mmrahmanbappi.github.io/100-free-html-templates/\">More free templates</a></p></div></footer>",
